const DocumentForm=({onDone}:{onDone:()=>void})=>{const [title,setTitle]=useState(''),[category,setCategory]=useState('supporting'),[audience,setAudience]=useState<'public'|'investor'|'restricted'|'internal'>('public'),[file,setFile]=useState<File|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');return <form onSubmit={async e=>{e.preventDefault();if(!file)return;setBusy(true);setError('');try{await uploadPortalDocument({file,title,category,audience,published:false});onDone()}catch(err){setError(err instanceof Error?err.message:'Upload gagal.')}finally{setBusy(false)}}} className="grid md:grid-cols-5 gap-3 p-4 mb-5 bg-black/[.025] rounded-xl"><input required className="field border-black/[.10] bg-white outline-none focus:ring-2 focus:ring-black/10" placeholder="Judul dokumen" value={title} onChange={e=>setTitle(e.target.value)}/><select className="field border-black/[.10] bg-white outline-none focus:ring-2 focus:ring-black/10" value={category} onChange={e=>setCategory(e.target.value)}><option value="investment_proposal">Proposal Investasi</option><option value="pitch_deck">Pitch Deck</option><option value="investor_report">Laporan Investor</option><option value="business_update">Pembaruan Bisnis</option><option value="supporting">Dokumen Pendukung</option></select><select className="field border-black/[.10] bg-white outline-none focus:ring-2 focus:ring-black/10" value={audience} onChange={e=>setAudience(e.target.value as 'public'|'investor'|'restricted'|'internal')}><option value="public">Publik</option><option value="investor">Semua Investor</option><option value="restricted">Investor Tertentu</option><option value="internal">Internal</option></select><input required className="field border-black/[.10] bg-white outline-none focus:ring-2 focus:ring-black/10" type="file" accept="application/pdf,.pdf" onChange={e=>setFile(e.target.files?.[0]||null)}/><button disabled={busy} className="btn justify-center">{busy?'Mengunggah...':'Upload Draft'}</button>{error&&<p className="md:col-span-5 text-xs text-red-600">{error}</p>}</form>};
const DocumentGrantBox=({doc,canAssign,canRevoke,onClose}:{doc:DocumentRow;canAssign:boolean;canRevoke:boolean;onClose:()=>void})=>{const [investors,setInvestors]=useState<InvestorRow[]>([]),[grants,setGrants]=useState<any[]>([]),[investor,setInvestor]=useState(''),[error,setError]=useState('');const load=()=>{void listInvestors().then(setInvestors);void listDocumentGrants(doc.id).then(setGrants).catch(e=>setError(e instanceof Error?e.message:'Gagal memuat akses.'))};useEffect(load,[doc.id]);return <div className="fixed inset-0 z-50 bg-black/40 flex items-center justify-center p-4"><div className="bg-white rounded-2xl p-6 w-full max-w-lg"><div className="flex justify-between"><div><h3 className="font-bold">Akses Investor</h3><p className="text-xs text-black/45 mt-1">{doc.title}</p></div><button onClick={onClose}><X size={18}/></button></div>{canAssign&&<div className="flex gap-2 my-5"><select className="field flex-1" value={investor} onChange={e=>setInvestor(e.target.value)}><option value="">Pilih investor</option>{investors.filter(i=>['approved','active'].includes(i.status)).map(i=><option key={i.user_id} value={i.user_id}>{i.investor_code||'—'} · {i.full_name}</option>)}</select><button className="btn" disabled={!investor} onClick={async()=>{try{await grantDocumentToInvestor(doc.id,investor);setInvestor('');load()}catch(e){setError(e instanceof Error?e.message:'Gagal memberi akses.')}}}>Berikan</button></div>}<div className="space-y-2">{grants.map((g:any)=>{const inv=Array.isArray(g.investors)?g.investors[0]:g.investors;return <div key={g.id} className="border rounded-xl p-3 flex justify-between gap-3"><div className="text-sm"><b>{inv?.legal_name||g.investor_id}</b><div className="text-xs text-black/45">{inv?.reference_code||'—'} · {g.revoked_at?'Dicabut':'Aktif'}</div></div>{canRevoke&&!g.revoked_at&&<button className="text-xs text-red-700" onClick={async()=>{await revokeDocumentGrant(g.id);load()}}>Cabut</button>}</div>})}</div>{error&&<p className="text-xs text-red-600 mt-3">{error}</p>}</div></div>};

